package vendor

import (
	"testing"

	"github.com/stretchr/testify/assert"
)

func TestRGB_Corrected_WhenGammaPositive_ShouldKeepPeakAndLowerWeakerChannels(t *testing.T) {
	t.Parallel()
	tests := []struct {
		name string
		in   RGB
		want RGB
	}{
		{"pastel green", RGB{0x80, 0xFF, 0x80}, RGB{0x17, 0xFF, 0x17}},
		{"light pastel green", RGB{0xC0, 0xFF, 0xC0}, RGB{0x5E, 0xFF, 0x5E}},
		{"material green", RGB{0x4C, 0xAF, 0x50}, RGB{0x09, 0xAF, 0x0B}},
		{"lime", RGB{0xA3, 0xE6, 0x35}, RGB{0x45, 0xE6, 0x01}},
		{"gold", RGB{0xFF, 0xD7, 0x00}, RGB{0xFF, 0x8C, 0x00}},
		{"sky blue below full brightness", RGB{0x00, 0xA3, 0xD7}, RGB{0x00, 0x52, 0xD7}},
		{"dark violet", RGB{0x4D, 0x22, 0xB3}, RGB{0x09, 0x01, 0xB3}},
		{"orange", RGB{0xFF, 0x80, 0x00}, RGB{0xFF, 0x17, 0x00}},
		{"weak channel floors at 1 instead of turning off", RGB{0x0A, 0xFF, 0x01}, RGB{0x01, 0xFF, 0x01}},
		{"near black", RGB{0x01, 0x02, 0x03}, RGB{0x01, 0x01, 0x03}},
		{"gray unchanged", RGB{0x80, 0x80, 0x80}, RGB{0x80, 0x80, 0x80}},
		{"white unchanged", RGB{0xFF, 0xFF, 0xFF}, RGB{0xFF, 0xFF, 0xFF}},
		{"primary unchanged", RGB{0xFF, 0x00, 0x00}, RGB{0xFF, 0x00, 0x00}},
		{"off unchanged", RGB{}, RGB{}},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			assert.Equal(t, tc.want, tc.in.Corrected(3.5))
		})
	}
}

func TestRGB_Corrected_WhenGammaNotPositive_ShouldReturnColorUnchanged(t *testing.T) {
	t.Parallel()
	c := RGB{0x4C, 0xAF, 0x50}
	assert.Equal(t, c, c.Corrected(0))
	assert.Equal(t, c, c.Corrected(-1))
}
